<?php
require_once __DIR__.'/_header.php';require_admin();$page_title='Human Story Submissions';
if(isset($_GET['reject'])){db()->prepare("UPDATE story_submissions SET status='REJECTED',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='SUBMITTED'")->execute([user()['id'],(int)$_GET['reject']]);log_admin_activity('reject_story_submission',(string)$_GET['reject']);flash('success','Submission rejected.');redirect('/admin/human-submissions.php');}
if(isset($_GET['approve'])){$id=(int)$_GET['approve'];try{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM story_submissions WHERE id=? AND status='SUBMITTED' FOR UPDATE");$s->execute([$id]);$submission=$s->fetch();if(!$submission)throw new RuntimeException('Submission is no longer pending.');$name=$submission['is_anonymous']?'Anonymous':($submission['storyteller_name']?:'Anonymous');$slug=slugify($submission['title']).'-'.$id;$year=$submission['event_date']?date('Y',strtotime($submission['event_date'])):null;$summary=mb_substr(preg_replace('/\s+/',' ',strip_tags($submission['story_content'])),0,220);$insert=$pdo->prepare("INSERT INTO stories(title,slug,story_type,event_date,year_label,location,image_path,summary,content,storyteller_name,storyteller_role,status,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$insert->execute([$submission['title'],$slug,'HUMAN',$submission['event_date']?:null,$year,$submission['location']?:null,$submission['image_path']?:null,$summary,$submission['story_content'],$name,$submission['storyteller_role']?:null,'PUBLISHED',user()['id'],user()['id']]);$pdo->prepare("UPDATE story_submissions SET status='APPROVED',reviewed_by=?,reviewed_at=NOW() WHERE id=?")->execute([user()['id'],$id]);$pdo->commit();log_admin_activity('approve_story_submission',(string)$id);flash('success','Human story published.');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error','Could not approve this submission.');}redirect('/admin/human-submissions.php');}
$rows=db()->query('SELECT * FROM story_submissions ORDER BY FIELD(status,"SUBMITTED","APPROVED","REJECTED"),created_at DESC')->fetchAll();
?><style>.submission-list{display:grid;gap:22px}.submission-preview{background:#fff;border:1px solid #ddd8d0;border-radius:12px;padding:28px;max-width:950px}.submission-preview h2{font:700 30px Georgia,serif;margin:8px 0 14px}.submission-meta{display:flex;flex-wrap:wrap;gap:8px 18px;color:#667;font-size:14px;margin-bottom:22px}.submission-body{border-top:1px solid #eee;padding-top:22px;font:17px/1.8 Georgia,serif;white-space:pre-line}.submission-photo{display:block;max-width:100%;max-height:420px;object-fit:contain;margin:22px 0;border:1px solid #ddd}.submission-status{display:inline-block;padding:6px 10px;border-radius:999px;background:#eee;font-size:12px;font-weight:700}.submission-status.submitted{background:#f7e4c2;color:#764d00}.submission-status.approved{background:#d9eedf;color:#17602c}.submission-status.rejected{background:#f3d9d7;color:#8a211c}.submission-actions{display:flex;gap:10px;flex-wrap:wrap;border-top:1px solid #eee;margin-top:24px;padding-top:20px}</style><div class="content"><div class="submission-list"><?php foreach($rows as $row):?><article class="submission-preview"><span class="submission-status <?=strtolower(e($row['status']))?>"><?=e($row['status'])?></span><h2><?=e($row['title'])?></h2><div class="submission-meta"><span><strong>Contributor:</strong> <?=e($row['is_anonymous']?'Anonymous':($row['storyteller_name']?:'No name'))?></span><?php if($row['storyteller_role']):?><span><strong>Role:</strong> <?=e($row['storyteller_role'])?></span><?php endif;?><?php if($row['email']):?><span><strong>Email:</strong> <?=e($row['email'])?></span><?php endif;?><?php if($row['location']):?><span><strong>Location:</strong> <?=e($row['location'])?></span><?php endif;?><?php if($row['event_date']):?><span><strong>Event date:</strong> <?=e($row['event_date'])?></span><?php endif;?><span><strong>Submitted:</strong> <?=e($row['created_at'])?></span></div><?php if($row['image_path']):?><img class="submission-photo" src="<?=BASE_URL?>/<?=e($row['image_path'])?>" alt="Photo submitted with <?=e($row['title'])?>"><?php endif;?><div class="submission-body"><?=e($row['story_content'])?></div><?php if($row['status']==='SUBMITTED'):?><div class="submission-actions"><a class="btn" data-confirm="Publish this human story?" href="?approve=<?=$row['id']?>">Approve &amp; publish</a><a class="btn danger" data-confirm="Reject this submission?" href="?reject=<?=$row['id']?>">Reject</a></div><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><div class="card">No submissions yet.</div><?php endif;?></div></div><?php require_once __DIR__.'/_footer.php';
